import{_ as a,c as t,o as i,b0 as l}from"./chunks/framework.Dmsv_Tiv.js";const s="/media-docs/assets/image-20251129085357451.BjM0X5l9.png",o="/media-docs/assets/image-20251202201611413.CUh0rW1B.png",r="/media-docs/assets/image-20251202201527500.DvNMJzM6.png",n="/media-docs/assets/image-20251129090319459.DAWjgF8I.png",_=JSON.parse('{"title":"LV001-VLC简介","description":null,"frontmatter":{"title":"LV001-VLC简介","date":"2025-12-02T20:06:31.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/avtools/vlc/126b19b6a4372a6c5bd39e95","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-12-02T20:06:31.678Z","fulluuid":"c5bd39e950d64bf4950dc3653d54f216","useduuid":"c5bd39e95"}},"headers":[],"relativePath":"sdoc/avtools/vlc/126b19b6a4372a6c5bd39e95.md","filePath":"sdoc/80-常用工具/10-VLC/LV001-VLC简介.md","lastUpdated":1767537778000}'),d={name:"sdoc/avtools/vlc/126b19b6a4372a6c5bd39e95.md"};function c(p,e,h,m,u,b){return i(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="lv001-vlc简介" tabindex="-1">LV001-VLC简介 <a class="header-anchor" href="#lv001-vlc简介" aria-label="Permalink to &quot;LV001-VLC简介&quot;">​</a></h1><h2 id="一、vlc简介" tabindex="-1">一、VLC简介 <a class="header-anchor" href="#一、vlc简介" aria-label="Permalink to &quot;一、VLC简介&quot;">​</a></h2><h3 id="_1-简介" tabindex="-1">1. 简介 <a class="header-anchor" href="#_1-简介" aria-label="Permalink to &quot;1. 简介&quot;">​</a></h3><p>我们直接看官网：<a href="https://www.videolan.org/" target="_blank" rel="noreferrer">VLC：官方网站 - 全平台的自由多媒体解决方案！ - VideoLAN</a></p><p>VLC（Video Lan Client）是一款自由、开源的跨平台多媒体播放器及框架，可播放大多数多媒体文件，以及 DVD、音频 CD、VCD 及各类流媒体协议。支持多种流媒体传输协议，也可当做本地流媒体服务器使用。</p><p>VLC 支持大量的音视频传输、封装和编码格式，下面给出一个简要的不完整的列表：</p><ul><li>操作系统： Windows、 WinCE、 Linux、 MacOSX、 BEOS、 BSD</li><li>访问形式： 文件、 DVD/VCD/CD、 http、 ftp、 mms、 TCP、 UDP、 RTP、 IP 组播、 IPv6、 rtsp</li><li>编码格式： MPEG*、 DIVX、 WMV、 MOV、 3GP、 FLV、 H.263、 H.264、 FLAC</li><li>视频字幕： DVD、 DVB、 Text、 Vobsub</li><li>视频输出： DirectX、 X11、 XVideo、 SDL、 FrameBuffer、 ASCII</li><li>控制界面： WxWidgets、 QT4、 Web、 Telnet、 Command line</li><li>浏览器插件： ActiveX、 Mozilla（firefox）</li></ul><h3 id="_2-下载安装" tabindex="-1">2. 下载安装 <a class="header-anchor" href="#_2-下载安装" aria-label="Permalink to &quot;2. 下载安装&quot;">​</a></h3><p>直接到官网下载安装即可：<a href="https://www.videolan.org/" target="_blank" rel="noreferrer">VLC：官方网站 - 全平台的自由多媒体解决方案！ - VideoLAN</a>，安装完成后打开，界面如下：</p><img src="'+s+`" alt="image-20251129085357451" style="zoom:50%;"><h2 id="二、基本应用" tabindex="-1">二、基本应用 <a class="header-anchor" href="#二、基本应用" aria-label="Permalink to &quot;二、基本应用&quot;">​</a></h2><h3 id="_1-播放视频" tabindex="-1">1. 播放视频 <a class="header-anchor" href="#_1-播放视频" aria-label="Permalink to &quot;1. 播放视频&quot;">​</a></h3><p>这个没啥说的，作为播放器，肯定最基本就是播放本地视频文件了。在播放视频的时候我们可以【工具】→【媒体信息】→【编解码器】/【统计】这里可以看到视频的一些信息，比如音频的类型，视频分辨率，帧率，编码格式，码率等信息。</p><h4 id="_2-打开网络串流" tabindex="-1">2. 打开网络串流 <a class="header-anchor" href="#_2-打开网络串流" aria-label="Permalink to &quot;2. 打开网络串流&quot;">​</a></h4><p>【媒体】→【打开网络串流】→【网络】→【网络协议中输入URL】，视频链接可以用下面这个：</p><div class="language-md vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http://devimages.apple.com/iphone/samples/bipbop/gear1/prog_index.m3u8</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">https://images.videolan.org/images/vlc-player.mp4</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><table><tbody><tr style="border:none;"><td align="center" style="border:none;"><img src="`+o+'" style="width:80%;height:auto;"></td><td align="center" style="border:none;"><img src="'+r+'" style="width:80%;height:auto;"></td></tr></tbody></table><p>最后点击播放就可以看到视频啦：</p><img src="'+n+'" alt="image-20251129090319459" style="zoom:67%;">',19)])])}const V=a(d,[["render",c]]);export{_ as __pageData,V as default};
